-- PT108-S3-Q12. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT108-S3-Q12$batch13$ AND q.stimulus=$batch13$Geologist: A geological fault in the mountain under which the proposed nuclear waste storage facility would be buried could, after a few thousand years, cause the contents to seep out or water to seep in. Since nuclear waste remains dangerous for up to 25,000 years, such seepage would be disastrous. So we should not place a nuclear waste storage facility under this mountain until scientists investigate whether this mountain has any geological faults.$batch13$ AND q.prompt=$batch13$Which one of the following, if true, most strengthens the geologist's argumentation?$batch13$ AND q.correct_choice=$batch13$B$batch13$) THEN RAISE EXCEPTION 'Question changed: PT108-S3-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT108-S3-Q12$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT108-S3-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT108-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$The facility shouldn't be placed under this mountain until scientists investigate whether it has any geological faults.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$A fault could let waste seep out or water seep in after a few thousand years. Nuclear waste stays dangerous for up to 25,000 years, so seepage would be disastrous.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$The geologist makes the investigation the condition for going ahead. That only makes sense if the investigation can settle the question. If the scientists might come back unsure, waiting for them wouldn't solve anything.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Show the investigation would actually answer whether faults exist.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT108-S3-Q12$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Whether civilization survives doesn't bear on whether to investigate first. If anything, it makes the danger seem less pressing.$batch13$), ($batch13$B$batch13$, $batch13$If the investigation gives a definite answer, it's worth waiting for. That's what the geologist's plan relies on.$batch13$), ($batch13$C$batch13$, $batch13$What the facility was first meant for doesn't affect the fault risk.$batch13$), ($batch13$D$batch13$, $batch13$A big cost increase is a reason against requiring the investigation.$batch13$), ($batch13$E$batch13$, $batch13$Temporary storage doesn't address the long-term seepage risk the argument is about.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT108-S3-Q12$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
